import{_ as s,o as i,c as a,a2 as o}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"Run Pi on Windows","description":"","frontmatter":{},"headers":[],"relativePath":"windows.md","filePath":"windows.md"}'),t={name:"windows.md"};function n(l,e,d,h,r,c){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="run-pi-on-windows" tabindex="-1">Run Pi on Windows <a class="header-anchor" href="#run-pi-on-windows" aria-label="Permalink to &quot;Run Pi on Windows&quot;">​</a></h1><p>Run Pi either as a native Windows process or inside Windows Subsystem for Linux (WSL). Native Windows uses Git Bash by default for Bash commands and can optionally expose PowerShell to the model. Pi inside WSL uses the Linux environment and its Bash installation.</p><p>Follow the main <a href="./quickstart.html">Quickstart</a> to install and authenticate Pi. Use this page to choose and configure its command environment.</p><h2 id="choose-native-windows-or-wsl" tabindex="-1">Choose native Windows or WSL <a class="header-anchor" href="#choose-native-windows-or-wsl" aria-label="Permalink to &quot;Choose native Windows or WSL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>Command environment</th><th>Use it when</th></tr></thead><tbody><tr><td>Native Windows with Git Bash</td><td>Git Bash for the built-in <code>bash</code> tool and <code>!</code> commands</td><td>Your files and development tools primarily live on Windows</td></tr><tr><td>Native Windows with the <code>powershell</code> tool</td><td>PowerShell for model tool calls; Bash remains available for <code>!</code> commands</td><td>The task depends on PowerShell modules or Windows-native commands</td></tr><tr><td>WSL</td><td>Linux Bash and tools inside the selected WSL distribution</td><td>Your files and toolchain already live in Linux or WSL</td></tr></tbody></table><h2 id="use-git-bash-on-native-windows" tabindex="-1">Use Git Bash on native Windows <a class="header-anchor" href="#use-git-bash-on-native-windows" aria-label="Permalink to &quot;Use Git Bash on native Windows&quot;">​</a></h2><p>For most native Windows users, installing <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git for Windows</a> is sufficient.</p><p>Pi resolves Bash in this order:</p><ol><li><code>shellPath</code> from <code>~/.pi/agent/settings.json</code></li><li>Git Bash at <code>%ProgramFiles%\\Git\\bin\\bash.exe</code></li><li>Git Bash at <code>%ProgramFiles(x86)%\\Git\\bin\\bash.exe</code></li><li><code>bash.exe</code> on <code>PATH</code>, including Cygwin, MSYS2, or legacy WSL Bash</li></ol><p>Start Pi and enter this command to verify the shell:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!printf &#39;Bash is working\\n&#39;</span></span></code></pre></div><p>If Pi cannot find Bash, it reports the locations it checked. Install Git for Windows, put another Bash executable on <code>PATH</code>, or configure <code>shellPath</code>.</p><h2 id="let-the-model-use-powershell" tabindex="-1">Let the model use PowerShell <a class="header-anchor" href="#let-the-model-use-powershell" aria-label="Permalink to &quot;Let the model use PowerShell&quot;">​</a></h2><p>The optional <code>powershell</code> tool runs commands through <code>pwsh.exe</code> when available, then falls back to Windows PowerShell. It starts PowerShell with <code>-NoProfile -NonInteractive -ExecutionPolicy Bypass</code>. Administrator-enforced execution policies can still take precedence.</p><p>PowerShell discovery checks these locations in order:</p><ol><li><code>pwsh.exe</code> on <code>PATH</code></li><li><code>%ProgramFiles%\\PowerShell\\7\\pwsh.exe</code></li><li><code>powershell.exe</code> on <code>PATH</code></li><li><code>%SystemRoot%\\System32\\WindowsPowerShell\\v1.0\\powershell.exe</code></li></ol><p>To replace the model-facing <code>bash</code> tool with <code>powershell</code>, add this to <code>~/.pi/agent/settings.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultTools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;powershell&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>[&quot;-bash&quot;, &quot;+powershell&quot;]</code> does the same while keeping any other default tools you configured.</p><p>Restart Pi, then ask it to run a harmless PowerShell command. The <code>!</code> and <code>!!</code> editor commands continue to use Bash. The <code>powershell</code> tool is available only when Pi runs as a native Windows process.</p><p>See <a href="./settings.html#tools">Settings</a> for other tool combinations.</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>WSL path conversion on Windows and extra Git branch polling in WSL recognize <code>/mnt/&lt;drive&gt;</code>, not custom mount roots.</p><p>When using the legacy WSL <code>bash.exe</code> launcher from Windows, Pi sends commands over stdin to avoid command-line quoting problems.</p><h2 id="use-a-custom-bash-executable" tabindex="-1">Use a custom Bash executable <a class="header-anchor" href="#use-a-custom-bash-executable" aria-label="Permalink to &quot;Use a custom Bash executable&quot;">​</a></h2><p>Set <code>shellPath</code> when Bash is installed somewhere Pi does not discover automatically:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shellPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cygwin64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bash.exe&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>JSON uses backslashes for escape sequences. When you write a Windows path with backslashes, write each backslash twice, as shown above.</p><p>See <a href="./shell-aliases.html">Configure shell commands</a> for command prefixes, aliases, and the complete shell-resolution behavior.</p><h2 id="configure-windows-terminal" tabindex="-1">Configure Windows Terminal <a class="header-anchor" href="#configure-windows-terminal" aria-label="Permalink to &quot;Configure Windows Terminal&quot;">​</a></h2><p>Windows Terminal reserves or rewrites some modified keys. See <a href="./terminal-setup.html#windows-terminal">Windows Terminal</a> to configure <code>Shift+Enter</code> and <code>Alt+Enter</code>, and <a href="./keybindings.html">Keybindings</a> for Pi&#39;s Windows and WSL shortcut defaults.</p>`,31)])])}const m=s(t,[["render",n]]);export{u as __pageData,m as default};
